fn list_quizzes(conn: &Connection) -> Vec<Quiz> {
    let mut stmt = conn
        .prepare("SELECT id, title, COALESCE(num_winners,3) FROM quizzes ORDER BY id ASC")
        .unwrap();
    let rows = stmt
        .query_map([], |row| {
            Ok(Quiz {
                id: row.get(0)?,
                title: row.get(1)?,
                num_winners: row.get(2).unwrap_or(3),
            })
        })
        .unwrap();
    rows.filter_map(|r| r.ok()).collect()
}

fn get_quiz(conn: &Connection, id: i64) -> Option<Quiz> {
    conn.query_row(
        "SELECT id, title, COALESCE(num_winners,3) FROM quizzes WHERE id=?1",
        params![id],
        |row| {
            Ok(Quiz {
                id: row.get(0)?,
                title: row.get(1)?,
                num_winners: row.get(2).unwrap_or(3),
            })
        },
    )
    .optional()
    .unwrap()
}

fn quiz_num_winners(quiz: &Quiz) -> i64 {
    if quiz.num_winners < 1 {
        3
    } else {
        quiz.num_winners
    }
}

fn count_questions(conn: &Connection, quiz_id: i64) -> (i64, i64) {
    let total: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM questions WHERE quiz_id=?1",
            params![quiz_id],
            |r| r.get(0),
        )
        .unwrap_or(0);
    let active: i64 = conn
        .query_row(
            "SELECT COUNT(*) FROM questions WHERE quiz_id=?1 AND active=1",
            params![quiz_id],
            |r| r.get(0),
        )
        .unwrap_or(0);
    (total, active)
}

