    }
    let conn = db_connect(&state).unwrap();
    // Number of winners for new quiz: default 3, validate if provided
    let nw_raw_opt = form
        .get("num_winners")
        .or(form.get("number_of_winners"))
        .or(form.get("winners"));
    let mut nw_val: i64 = 3;
    if let Some(raw) = nw_raw_opt {
