fn get_game_by_code(conn: &Connection, code: &str) -> Option<Game> {
    let upper = code.trim().to_uppercase();
    // Try with question_opened_at; fallback if column missing (old DB before migration)
    if let Ok(mut stmt) = conn.prepare(
        "SELECT id, quiz_id, code, status, current_question_id, question_opened_at FROM games WHERE code=?1",
    ) {
        if let Ok(opt) = stmt
            .query_row(params![upper], |row| {
                let cq: Option<i64> = row.get(4)?;
                let opened: Option<i64> = row.get(5).unwrap_or(None);
                Ok(Game {
                    id: row.get(0)?,
                    quiz_id: row.get(1)?,
                    code: row.get(2)?,
                    status: row.get(3)?,
                    current_question_id: cq,
                    question_opened_at: opened,
                })
            })
            .optional()
        {
            if opt.is_some() {
                return opt;
            }
        }
    }
    conn.query_row(
        "SELECT id, quiz_id, code, status, current_question_id FROM games WHERE code=?1",
        params![upper],
        |row| {
            let cq: Option<i64> = row.get(4)?;
            Ok(Game {
                id: row.get(0)?,
                quiz_id: row.get(1)?,
                code: row.get(2)?,
                status: row.get(3)?,
                current_question_id: cq,
                question_opened_at: None,
            })
        },
    )
    .optional()
    .unwrap()
}

