fn counts_per_option(
    conn: &Connection,
    game_id: i64,
    question_id: i64,
) -> HashMap<i64, i64> {
    let mut map = HashMap::new();
    let mut stmt = match conn.prepare(
        "SELECT option_id, COUNT(*) FROM answers WHERE game_id=?1 AND question_id=?2 GROUP BY option_id",
    ) {
        Ok(s) => s,
        Err(_) => return map,
    };
    if let Ok(rows) = stmt.query_map(params![game_id, question_id], |row| {
        let oid: i64 = row.get(0)?;
        let c: i64 = row.get(1)?;
        Ok((oid, c))
    }) {
        for r in rows.flatten() {
            map.insert(r.0, r.1);
        }
    }
    map
}

fn get_player_by_token(conn: &Connection, game_id: i64, token: &str) -> Option<Player> {
    let t = token.trim().trim_matches('"');
    if t.is_empty() {
        return None;
    }
    // tokens are hex; ignore obviously wrong
    conn.query_row(
        "SELECT id, game_id, name, token FROM players WHERE game_id=?1 AND token=?2",
        params![game_id, t],
        |row| {
            Ok(Player {
                id: row.get(0)?,
                game_id: row.get(1)?,
                name: row.get(2)?,
                token: row.get(3)?,
            })
        },
    )
    .optional()
    .unwrap()
}

fn find_player_for_game(
    conn: &Connection,
    game: &Game,
    headers: &HeaderMap,
    query_token: Option<&str>,
