fn do_start(conn: &Connection, game: &Game) -> Game {
    if game.status != "lobby" {
        return game.clone();
    }
    let active = active_questions_for(conn, game.quiz_id);
    if active.is_empty() {
        conn.execute("UPDATE games SET status='finished', current_question_id=NULL WHERE id=?1", params![game.id]).unwrap();
        let mut g = game.clone();
        g.status = "finished".to_string();
        g.current_question_id = None;
        return g;
    }
    let first = &active[0];
    let now = now_ms();
    // Update with opened_at; fallback if column missing
    if conn
        .execute(
            "UPDATE games SET status='open', current_question_id=?1, question_opened_at=?2 WHERE id=?3",
            params![first.id, now, game.id],
        )
        .is_err()
    {
        let _ = conn.execute(
            "UPDATE games SET status='open', current_question_id=?1 WHERE id=?2",
            params![first.id, game.id],
        );
    }
    let mut g = game.clone();
    g.status = "open".to_string();
    g.current_question_id = Some(first.id);
    g.question_opened_at = Some(now);
    g
}

fn do_finish(conn: &Connection, game: &Game) -> Game {
    if game.status != "open" {
        return game.clone();
    }
    conn.execute("UPDATE games SET status='closed' WHERE id=?1", params![game.id]).unwrap();
    let mut g = game.clone();
    g.status = "closed".to_string();
    g
}

fn do_next(conn: &Connection, game: &Game) -> Game {
    if game.status != "closed" {
        return game.clone();
    }
    let active = active_questions_for(conn, game.quiz_id);
    if active.is_empty() {
        conn.execute("UPDATE games SET status='finished' WHERE id=?1", params![game.id]).unwrap();
        let mut g = game.clone();
        g.status = "finished".to_string();
        return g;
    }
    let cur = game.current_question_id;
    let idx = cur.and_then(|cid| active.iter().position(|q| q.id == cid));
    if let Some(i) = idx {
        if i + 1 < active.len() {
            let nxt = &active[i + 1];
            let now = now_ms();
            if conn
                .execute(
                    "UPDATE games SET status='open', current_question_id=?1, question_opened_at=?2 WHERE id=?3",
                    params![nxt.id, now, game.id],
                )
                .is_err()
            {
                let _ = conn.execute(
                    "UPDATE games SET status='open', current_question_id=?1 WHERE id=?2",
                    params![nxt.id, game.id],
                );
            }
            let mut g = game.clone();
            g.status = "open".to_string();
            g.current_question_id = Some(nxt.id);
            g.question_opened_at = Some(now);
            return g;
        } else {
            // last -> finish
            conn.execute("UPDATE games SET status='finished' WHERE id=?1", params![game.id]).unwrap();
            let mut g = game.clone();
            g.status = "finished".to_string();
            return g;
        }
    } else {
        // current not in active (deactivated?) -> go to first?
        // Find next after position? Simplest: go to first active
        let nxt = &active[0];
        // If game had no valid current, start at first open?
        // But this is Next from closed with invalid current: just finish? Let's go to first.
        let now = now_ms();
        if conn
            .execute(
                "UPDATE games SET status='open', current_question_id=?1, question_opened_at=?2 WHERE id=?3",
                params![nxt.id, now, game.id],
            )
            .is_err()
        {
            let _ = conn.execute(
                "UPDATE games SET status='open', current_question_id=?1 WHERE id=?2",
                params![nxt.id, game.id],
            );
        }
        let mut g = game.clone();
        g.status = "open".to_string();
        g.current_question_id = Some(nxt.id);
        g.question_opened_at = Some(now);
        return g;
    }
}

fn do_end(conn: &Connection, game: &Game) -> Game {
    if game.status == "finished" {
        return game.clone();
    }
    conn.execute("UPDATE games SET status='finished' WHERE id=?1", params![game.id]).unwrap();
    let mut g = game.clone();
    g.status = "finished".to_string();
    g
}

async fn game_action_handler(
    State(state): State<AppState>,
    Path(code): Path<String>,
    headers: HeaderMap,
    action: &str,
) -> Response {
    let conn = db_connect(&state).unwrap();
    let Some(game) = get_game_by_code(&conn, &code) else {
        if wants_json(&headers) {
            return (StatusCode::NOT_FOUND, axum::Json(serde_json::json!({"error":"not found"}))).into_response();
        } else {
            return (StatusCode::NOT_FOUND, Html(admin_layout("Not found", "<h1>Game not found</h1>"))).into_response();
        }
    };
    let new_game = match action {
        "start" => do_start(&conn, &game),
        "finish" => do_finish(&conn, &game),
        "next" => do_next(&conn, &game),
        "end" => do_end(&conn, &game),
        _ => game.clone(),
    };
    if wants_json(&headers) {
        let quiz = get_quiz(&conn, new_game.quiz_id).unwrap_or(Quiz { id: new_game.quiz_id, title: String::new(), num_winners: 3 });
        let host = host_from_headers(&headers);
        let st = build_mod_state(&conn, &new_game, &quiz, &host);
        axum::Json(st).into_response()
    } else {
        Redirect::to(&format!("/moderate/games/{}", new_game.code)).into_response()
    }
}

async fn game_start_handler(
    State(state): State<AppState>,
    Path(code): Path<String>,
    headers: HeaderMap,
) -> impl IntoResponse {
    game_action_handler(State(state), Path(code), headers, "start").await
}
async fn game_finish_handler(
    State(state): State<AppState>,
    Path(code): Path<String>,
    headers: HeaderMap,
) -> impl IntoResponse {
    game_action_handler(State(state), Path(code), headers, "finish").await
}
async fn game_next_handler(
    State(state): State<AppState>,
    Path(code): Path<String>,
    headers: HeaderMap,
) -> impl IntoResponse {
    game_action_handler(State(state), Path(code), headers, "next").await
}
async fn game_end_handler(
    State(state): State<AppState>,
    Path(code): Path<String>,
    headers: HeaderMap,
) -> impl IntoResponse {
    game_action_handler(State(state), Path(code), headers, "end").await
}

async fn winners_action_handler(
    State(state): State<AppState>,
    Path(code): Path<String>,
    headers: HeaderMap,
    action: &str,
) -> Response {
    let conn = db_connect(&state).unwrap();
    let Some(game) = get_game_by_code(&conn, &code) else {
        if wants_json(&headers) {
            return (StatusCode::NOT_FOUND, axum::Json(serde_json::json!({"error":"not found"}))).into_response();
        } else {
            return (StatusCode::NOT_FOUND, Html(admin_layout("Not found", "<h1>Game not found</h1>"))).into_response();
        }
    };
    let quiz = get_quiz(&conn, game.quiz_id).unwrap_or(Quiz { id: game.quiz_id, title: String::new(), num_winners: 3 });
    // Only pick winners when finished; otherwise just return state
    if game.status == "finished" {
        let scores = compute_scores(&conn, game.id);
        let n = quiz_num_winners(&quiz).max(1) as usize;
        match action {
            "top" => {
                let ids = compute_top_winner_ids(&scores, n);
                set_winners(&conn, game.id, &ids);
            }
            "draw" => {
                let ids = compute_draw_winner_ids(&scores, n);
                set_winners(&conn, game.id, &ids);
            }
            "reset" => {
                set_winners(&conn, game.id, &[]);
            }
            _ => {}
        }
    }
    if wants_json(&headers) {
        let game2 = get_game_by_code(&conn, &code).unwrap_or(game);
        let host = host_from_headers(&headers);
        let st = build_mod_state(&conn, &game2, &quiz, &host);
        axum::Json(st).into_response()
    } else {
        Redirect::to(&format!("/moderate/games/{}", game.code)).into_response()
    }
}

