    let sql = format!("PRAGMA table_info({})", table);
    if let Ok(mut stmt) = conn.prepare(&sql) {
        if let Ok(rows) = stmt.query_map([], |row| {
            let name: String = row.get(1)?;
            Ok(name)
        }) {
            for r in rows.flatten() {
                if r == column {
                    return true;
                }
            }
        }
    }
    false
}

