}

fn list_players(conn: &Connection, game_id: i64) -> Vec<Player> {
    let mut stmt = match conn.prepare(
        "SELECT id, game_id, name, token FROM players WHERE game_id=?1 ORDER BY id ASC",
    ) {
        Ok(s) => s,
        Err(_) => return Vec::new(),
    };
    let rows = stmt
        .query_map(params![game_id], |row| {
            Ok(Player {
                id: row.get(0)?,
                game_id: row.get(1)?,
                name: row.get(2)?,
                token: row.get(3)?,
            })
        })
        .unwrap();
    rows.filter_map(|r| r.ok()).collect()
}

fn get_winners_set(conn: &Connection, game_id: i64) -> std::collections::HashSet<i64> {
    let mut set = std::collections::HashSet::new();
    if let Ok(mut stmt) = conn.prepare("SELECT player_id FROM game_winners WHERE game_id=?1") {
        if let Ok(rows) = stmt.query_map(params![game_id], |row| {
            let pid: i64 = row.get(0)?;
            Ok(pid)
        }) {
            for r in rows.flatten() {
                set.insert(r);
            }
        }
    }
    set
}

fn set_winners(conn: &Connection, game_id: i64, player_ids: &[i64]) {
    let _ = conn.execute("DELETE FROM game_winners WHERE game_id=?1", params![game_id]);
    for pid in player_ids {
        let _ = conn.execute(
            "INSERT OR IGNORE INTO game_winners (game_id, player_id) VALUES (?1, ?2)",
            params![game_id, pid],
        );
    }
}

fn random_shuffle<T>(v: &mut [T]) {
    let n = v.len();
    if n <= 1 {
        return;
    }
    let bytes = game_random_bytes(n * 4);
    for i in (1..n).rev() {
        let off = i * 4;
        let r = if off + 4 <= bytes.len() {
            u32::from_be_bytes([bytes[off], bytes[off + 1], bytes[off + 2], bytes[off + 3]]) as usize
        } else {
            (now_ms() as usize).wrapping_add(i * 0x9e3779b9)
        };
        let j = r % (i + 1);
        v.swap(i, j);
    }
}

